function validate([arr]) {
  if (!Array.isArray(arr) || arr.length < 1 || arr.length > 100000) return 'arr needs 1 to 10^5 values.';
  if (arr.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Each value is an integer from 1 to 100.';
  return null;
}

