function numOfSubarrays(arr) {
  const MOD = 1_000_000_007;
  let evenPrefixes = 1;
  let oddPrefixes = 0;
  let parity = 0;
  let count = 0;

  for (const value of arr) {
    parity = (parity + value) % 2;
    if (parity === 1) {
      count = (count + evenPrefixes) % MOD;
      oddPrefixes++;
    } else {
      count = (count + oddPrefixes) % MOD;
      evenPrefixes++;
    }
  }
  return count;
}

