function numOfSubarrays(arr) {
  let odd = 0;
  for (let i = 0; i < arr.length; i++) {
    let total = 0;
    for (let j = i; j < arr.length; j++) {
      total += arr[j];
      if (total % 2 !== 0) odd++;
