function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? pick(1500, 2000) : pick(1, 10);
  const style = rand();
  const arr = Array.from({ length: n }, () => {
    if (style < 0.15) return 2 * pick(1, 50);
    if (style < 0.3) return 2 * pick(0, 49) + 1;
    if (style < 0.5) return rand() < 0.15 ? 2 * pick(0, 49) + 1 : 2 * pick(1, 50);
    return pick(1, size === 'large' ? 100 : pick(1, 100));
  });
  return [arr];
}
